# Render the fixed gate outcomes without changing calibration or simulation.
if(dir.exists('.local/R-library')) .libPaths(c(normalizePath('.local/R-library'),.libPaths()))
source('R/scp_calibrate.R');started<-proc.time()[['elapsed']];out<-'reports/M2'
s<-read.csv(file.path(out,'fidelity-summary.csv'));checks<-read.csv(file.path(out,'fidelity-table.csv'));reps<-read.csv(file.path(out,'replicate-metrics.csv'));obs<-read.csv(file.path(out,'observed-metrics.csv'));bins<-read.csv(file.path(out,'missingness-intensity-bins.csv'))
m<-jsonlite::read_json(file.path(out,'run-manifest.json'),simplifyVector=FALSE);vt<-paste(names(.scp_versions()),.scp_versions(),sep='=',collapse='; ')
footer<-function(){mtext('Registered native designs; beta=0; 20 independent replicates; no calibration or simulator retuning.',side=1,outer=TRUE,line=1,cex=.65,xpd=NA);mtext(vt,side=1,outer=TRUE,line=2.2,cex=.48,xpd=NA)}
png(file.path(out,'missingness-observed-simulated.png'),width=2100,height=1250,res=180);par(mfrow=c(2,3),mar=c(4,4,4,1),oma=c(4,0,2,0))
for(n in s$dataset){d<-bins[bins$dataset==n,];o<-d[d$source=='observed',];sim<-d[d$source=='simulated',];pooled<-do.call(rbind,lapply(sort(unique(sim$bin)),function(b){x<-sim[sim$bin==b,];data.frame(bin=b,mean_log2=weighted.mean(x$mean_log2,x$proteins),missing_fraction=weighted.mean(x$missing_fraction,x$proteins))}));plot(o$mean_log2,o$missing_fraction,pch=16,col='#1680a1',xlab='Mean observed log2 intensity',ylab='Missing fraction (fixed intensity bins)',ylim=c(0,1),xlim=range(c(o$mean_log2,pooled$mean_log2)),main=n);points(pooled$mean_log2,pooled$missing_fraction,pch=17,col='#b85555');mtext(s$status[s$dataset==n],side=3,line=.2,col=if(s$status[s$dataset==n]=='PASS')'#216b38' else '#b22222',cex=.8,xpd=NA);par(xpd=FALSE)}
plot.new();legend('center',legend=c('Observed raw-input mask','Pooled simulated replicates'),pch=c(16,17),col=c('#1680a1','#b85555'),bty='n',cex=.9);footer();dev.off()
png(file.path(out,'cell-sd-observed-simulated.png'),width=2100,height=1250,res=180);par(mfrow=c(2,3),mar=c(4,4,4,1),oma=c(4,0,2,0))
for(n in s$dataset){o<-obs[obs$dataset==n,];r<-reps[reps$dataset==n,];average<-vapply(o$tier,function(t)mean(r$cell_sd[r$tier==t]),numeric(1));variation<-vapply(o$tier,function(t)sd(r$cell_sd[r$tier==t]),numeric(1));plot(o$tier,o$cell_sd,pch=16,col='#1680a1',ylim=c(0,max(c(o$cell_sd,average+variation),na.rm=TRUE)*1.1),xlab='Accepted abundance tier',ylab='Median within-line cell SD (log2)',main=n);points(o$tier+.08,average,pch=17,col='#b85555');arrows(o$tier+.08,average-variation,o$tier+.08,average+variation,angle=90,code=3,length=.04,col='#b85555');par(xpd=NA);title(main=n);mtext(s$status[s$dataset==n],side=3,line=.2,col=if(s$status[s$dataset==n]=='PASS')'#216b38' else '#b22222',cex=.8,xpd=NA);par(xpd=FALSE)}
plot.new();legend('center',legend=c('Observed','Simulated mean; bars = replicate SD'),pch=c(16,17),col=c('#1680a1','#b85555'),bty='n',cex=.85);footer();dev.off()
f<-function(x,d=3)ifelse(is.finite(x),format(round(x,d),nsmall=d,trim=TRUE),'NA')
lines<-c('# M2 simulator fidelity report','13 October 2026. Frozen addendum v1.1.2. Every dataset uses its exact cell-line-by-acquisition-batch counts and beta=0. Each comparison averages the registered independent replicates. Every applicable tier must pass; no failing tier is averaged away.','', '| Dataset | Gate | Missingness maximum error (pp) | Coverage relative error | Cell SD maximum relative error | Batch SD maximum relative error |','| --- | --- | ---: | ---: | ---: | ---: |')
for(i in seq_len(nrow(s)))lines<-c(lines,sprintf('| %s | %s | %s | %s%% | %s%% | %s |',s$dataset[i],s$status[i],f(100*s$maximum_missingness_error[i],2),f(100*s$coverage_relative_error[i],1),f(100*s$maximum_cell_sd_error[i],1),if(is.finite(s$maximum_batch_sd_error[i]))paste0(f(100*s$maximum_batch_sd_error[i],1),'%') else 'Not applicable (F)'))
lines<-c(lines,'','Registered tolerances: missing fraction per tier within 5 percentage points; proteins per cell within 10% relative; median within-line cell SD per tier within 20% relative; between-batch SD per tier within 25% relative where separately identified. Brunner has no separate batch component under F.','', 'The [full fidelity table](fidelity-table.csv) gives observed values, simulated means, errors, tolerances and PASS/FAIL for every quantity and tier. [Replicate metrics](replicate-metrics.csv) preserve all draws and seeds.','', 'Suspected causes are interpretations of these fixed outcomes, not changes to the implementation:','')
for(n in s$dataset) {
 bad<-checks[checks$dataset==n&checks$applicable&!checks$pass,]
 if(!nrow(bad))lines<-c(lines,paste0('- ',n,': PASS on all applicable quantities.')) else {
  cause<-character();if(any(bad$metric=='missing_fraction'))cause<-c(cause,if(n%in%c('specht2019v3','leduc2022_pSCoPE'))'one global intensity curve cannot reproduce all retained tier masks; TMT tiers retain the accepted ratio scale while their predictor is raw intensity, and identification availability is heterogeneous' else 'resampling observed means and adding sample/batch effects can alter tier-specific coverage; an intensity-only curve also omits protein-specific identification availability')
  if(any(bad$metric=='mean_proteins_per_cell'))cause<-c(cause,'expected-intensity masking with resampled observed means and injected sample/batch effects changes total quantification coverage')
  if(any(bad$metric=='cell_sd'))cause<-c(cause,'the unweighted mean of heterogeneous protein variances generates an RMS scale and need not reconstruct the median measured within-line SD; observed selection and normalization also differ')
  if(any(bad$metric=='batch_sd'))cause<-c(cause,'pooled latent batch variance need not reproduce median noisy batch-mean SD, especially with sparse observation and differing cell-line means')
  lines<-c(lines,paste0('- ',n,': FAIL; ',paste(unique(cause),collapse='; '),'.'))
 }
}
lines<-c(lines,'', 'Specht retains a weak negative fitted raw-intensity slope, flagged in final M1. It was not replaced by MCAR or forced positive for this gate. Failed datasets stop at this report. No parameter, preset, missingness definition, or tolerance was altered to obtain a pass.','', 'Missingness and coverage use the paired raw PSM mask for TMT and the selected quantitative protein mask for DIA. Cell SD uses the accepted variance assay after per-cell median shifts; the same shift is applied to simulations. It is the median over measured protein-by-line SDs within each tier. Batch SD is the median of protein-level SDs across mixed-batch means after line-mean subtraction. The figures bin intensities for display only; they do not alter the curves or gate tests.','', 'Cell lines are culture samples. The injected Walzik variance remains a whole-PBMC proxy, including donor composition differences; M2 cannot validate bulk-to-cell-line donor transfer. The registered M4 criterion is unchanged.','', paste('Software:',vt))
writeLines(lines,file.path(out,'fidelity-report.md'))
writeLines(c('# M2 evidence','', '[Fidelity report](fidelity-report.md), [full gate table](fidelity-table.csv), [summary](fidelity-summary.csv), [missingness plot](missingness-observed-simulated.png), [cell SD plot](cell-sd-observed-simulated.png), [run manifest](run-manifest.json).','', 'The gate is reported without tuning. A failed dataset stops; the next directive determines any change. Simulator tests and package CI are separate from scientific fidelity outcomes.'),file.path(out,'README.md'))
m$report_generation<-list(seed=20261013,versions=as.list(.scp_versions()),input_hashes=list(gate_table=digest::digest(file=file.path(out,'fidelity-table.csv'),algo='sha256'),replicate_metrics=digest::digest(file=file.path(out,'replicate-metrics.csv'),algo='sha256')),wall_seconds=proc.time()[['elapsed']]-started)
m$decision<-list(status='Completed registered M2 gate; all failures reported without tuning',passed_datasets=as.list(s$dataset[s$status=='PASS']),failed_datasets=as.list(s$dataset[s$status=='FAIL']),next_directive_decides_changes=TRUE,no_scp_power_or_M4_work=TRUE)
jsonlite::write_json(m,file.path(out,'run-manifest.json'),pretty=TRUE,auto_unbox=TRUE,na='null',digits=NA)
